// GET /api/accuracy — daily + monthly accuracy tables (JSON).
// Serves the static files regenerated by the evidence tracker (gen-rugs-html.mjs).
// Cache API 5 min. No secrets. Read-only.
const json = (status, body, extra = {}) => new Response(typeof body === 'string' ? body : JSON.stringify(body), {
  status, headers: { 'content-type': 'application/json; charset=utf-8', 'access-control-allow-origin': '*', ...extra },
});

export const onRequest = async ({ request: req, waitUntil }) => {
  if (req.method === 'OPTIONS') return new Response(null, { status: 204, headers: { 'access-control-allow-origin': '*', 'access-control-allow-methods': 'GET, OPTIONS' } });
  if (req.method !== 'GET') return json(405, { error: 'GET only' });
  const u = new URL(req.url);
  const which = (u.searchParams.get('view') || 'daily').toLowerCase(); // daily | monthly | all
  const cache = typeof caches !== 'undefined' ? caches.default : null;
  const key = new Request('https://memecheck-cache.internal/accuracy/' + which + '/v1');
  try {
    const hit = cache && await cache.match(key);
    if (hit) return json(200, await hit.text(), { 'cache-control': 'public, max-age=120', 'x-cache': 'HIT' });
  } catch {}

  const origin = u.origin;
  const get = async (path) => {
    try {
      const r = await fetch(new URL(path, origin), { cf: { cacheTtl: 60 } });
      if (!r.ok) return null;
      return await r.json();
    } catch { return null; }
  };
  const daily = await get('/accuracy-daily.json');
  const monthly = await get('/accuracy-monthly.json');
  if (!daily && !monthly) return json(503, { ok: false, error: 'accuracy files not generated yet' });

  let body;
  if (which === 'monthly') body = { ok: true, ...(monthly || {}) };
  else if (which === 'all') body = { ok: true, daily, monthly };
  else body = { ok: true, ...(daily || {}) };

  const txt = JSON.stringify(body);
  if (cache) {
    const p = cache.put(key, new Response(txt, { headers: { 'content-type': 'application/json', 'cache-control': 'public, max-age=300' } })).catch(() => {});
    waitUntil ? waitUntil(p) : await p;
  }
  return json(200, txt, { 'cache-control': 'public, max-age=120', 'x-cache': 'MISS' });
};
